class Vault {
public:
    Record read(const Subject& who, Id id) const {
        if (!policy_.allows(who, id)) throw AccessDenied(id);   // decision and access in one call
        return store_.get(id);
    }
private:
    Store store_;                    // no getter, no friend, no cast hook: single entry point
    Policy policy_;
};
// one collaborator needs one privileged call: a passkey token, not a blanket friend
